function report=capture_ui_callbacks_017(app,phase)
% Parent-side read-only inventory. Never invoke callbacks or calculate.
assert(isvalid(app) && ~app.Busy && ~app.SimulationMode && ~app.MapEditMode);
root=fileparts(fileparts(mfilename('fullpath')));
folder=fullfile(root,'outputs','ui_all_callbacks_20261031','parent_independent');
if ~isfolder(folder), mkdir(folder); end
jsonFile=fullfile(folder,[phase '.json']); backupFile=fullfile(folder,[phase '.mat']);
assert(~isfile(jsonFile) && ~isfile(backupFile));
backup=app.snapshotModelSwitchState(); seedText=app.AutoTuneSeed.Text;
save(backupFile,'backup','seedText','-v7');
loaded=load(backupFile); assert(isequaln(loaded.backup,backup));
figures={app.Figure};
if ~isempty(app.DiagnosticsFigure) && isgraphics(app.DiagnosticsFigure), figures{end+1}=app.DiagnosticsFigure; end
inventory=struct('figure',{},'class',{},'tag',{},'text',{},'property',{},'type',{},'function',{});
for f=1:numel(figures)
    objects=findall(figures{f});
    for k=1:numel(objects)
        object=objects(k); names=properties(object);
        for n=1:numel(names)
            name=names{n};
            if isempty(regexp(name,'(Fcn|Callback)$','once')), continue; end
            callback=object.(name); if isempty(callback), continue; end
            entry=struct('figure',f,'class',class(object),'tag','','text','', ...
                'property',name,'type',class(callback),'function','');
            if isprop(object,'Tag'), entry.tag=object.Tag; end
            if isprop(object,'Text'), entry.text=object.Text; end
            handle=callback; if iscell(callback), handle=callback{1}; end
            if isa(handle,'function_handle'), entry.function=func2str(handle);
            elseif ischar(handle) || isstring(handle), entry.function=char(handle); end
            inventory(end+1)=entry; %#ok<AGROW>
        end
    end
end
report=struct('phase',phase,'backupFile',backupFile,'callbackCount',numel(inventory), ...
    'inventory',inventory,'stateUnchanged',isequaln(backup,app.snapshotModelSwitchState()), ...
    'scope','Read-only callback inventory and full snapshot; no callbacks invoked or route calculation.');
fid=fopen(jsonFile,'w','n','UTF-8'); assert(fid>=0); closer=onCleanup(@()fclose(fid));
fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
fprintf('CALLBACK_INVENTORY_%s count=%d stateUnchanged=%d\n',phase,numel(inventory),report.stateUnchanged);
end

function report=probe_ui_layout_callback_017(app,phase)
% The layout callback only sets view dimensions; never runs the model.
assert(isvalid(app) && ~app.Busy && ~app.SimulationMode && ~app.MapEditMode);
root=fileparts(fileparts(mfilename('fullpath')));
path=fullfile(root,'outputs','ui_all_callbacks_20261031','parent_independent',[phase '_layout.json']);
assert(~isfile(path));
before=app.snapshotModelSwitchState(); callback=app.Figure.SizeChangedFcn;
report=struct('property','Figure.SizeChangedFcn','succeeded',false,'identifier','','message','');
try
    if iscell(callback), feval(callback{1},app.Figure,[],callback{2:end});
    else, feval(callback,app.Figure,[]); end
    report.succeeded=true;
catch ex
    report.identifier=ex.identifier; report.message=ex.message;
end
report.stateUnchanged=isequaln(before,app.snapshotModelSwitchState());
assert(report.stateUnchanged);
fid=fopen(path,'w','n','UTF-8'); assert(fid>=0); closer=onCleanup(@()fclose(fid));
fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
fprintf('LAYOUT_CALLBACK_%s success=%d stateUnchanged=%d %s\n',phase,report.succeeded,report.stateUnchanged,report.identifier);
end

function report=verify_ui_callbacks_017(app)
root=fileparts(fileparts(mfilename('fullpath')));
folder=fullfile(root,'outputs','ui_all_callbacks_20261031','parent_independent');
out=fullfile(folder,'verification.json'); assert(~isfile(out));
capture_ui_callbacks_017(app,'after');
layout=probe_ui_layout_callback_017(app,'after'); assert(layout.succeeded);
before=jsondecode(fileread(fullfile(folder,'before.json')));
after=jsondecode(fileread(fullfile(folder,'after.json')));
oldNames={before.inventory.function}; newNames={after.inventory.function};
oldApp=contains(oldNames,'app.') | strcmp(oldNames,'cam_app_ui_dispatch');
newApp=contains(newNames,'app.') | strcmp(newNames,'cam_app_ui_dispatch');
anonymousCount=nnz(startsWith(newNames,'@') & contains(newNames,'app.'));
namedCount=nnz(strcmp(newNames,'cam_app_ui_dispatch'));
frameworkPreserved=isequaln(before.inventory(~oldApp),after.inventory(~newApp));
saved=load(fullfile(folder,'before.mat'),'backup');
modelPreserved=isequaln(saved.backup,app.snapshotModelSwitchState());
[plan,audit]=cam_app_ui_binding_plan(app);
namedBindings=all(arrayfun(@(p)cam_app_ui_callback_matches(p.control.(p.property),app,p.key),plan));
assert(anonymousCount==0 && namedCount==67 && frameworkPreserved && modelPreserved && namedBindings && isempty(audit.unknown));
report=struct('callbackCountBefore',before.callbackCount,'callbackCountAfter',after.callbackCount, ...
    'appAnonymousAfter',anonymousCount,'appNamedAfter',namedCount,'frameworkCount',nnz(~newApp), ...
    'frameworkPreserved',frameworkPreserved,'initialModelInputsResultsPreserved',modelPreserved, ...
    'allBindingsMatch',namedBindings,'unknownCallbacks',numel(audit.unknown),'layoutCallback',layout, ...
    'scope','Independent before/after inventory and model snapshot. Only layout callback executed; no route/calculation/optimization/import/export/apply/reset business.');
fid=fopen(out,'w','n','UTF-8'); assert(fid>=0); closer=onCleanup(@()fclose(fid)); fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
fprintf('LIVE_CALLBACK_VERIFY_PASS named=%d framework=%d anonymous=%d modelPreserved=%d\n',namedCount,nnz(~newApp),anonymousCount,modelPreserved);
end
